// Refresh experiment/ComixBundle.ts from the live site through a real Chrome
// (npm run refresh:comix uses Node fetch, which Cloudflare challenges). Uses the
// secure-*.js URL + cfg from capture.json (run capture.mjs first), downloads
// secure.js inside the page, and packages it exactly like RefreshComixBundle.ts.
//
//   node experiment/live/capture.mjs && node experiment/live/refresh-bundle.mjs

import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { launch } from "./cdp.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const OUT = resolve(HERE, "../ComixBundle.ts");
const cap = JSON.parse(readFileSync(join(HERE, "capture.json"), "utf8"));
if (!cap.secureUrl || !cap.cfg) throw new Error("capture.json has no secureUrl/cfg — rerun capture.mjs");

const b = await launch();
let text;
try {
  await b.goto("https://comix.to/", 1500);
  const r = await b.fetchText(cap.secureUrl, { Accept: "application/javascript,*/*;q=0.9" });
  if (r.status !== 200 || !/export\s*\{/.test(r.text)) throw new Error(`secure.js download failed: HTTP ${r.status}`);
  text = r.text;
} finally {
  b.close();
}

// `export {x as y, …}` → `;return {y:x, …};` (same transform as RefreshComixBundle.ts)
const m = text.match(/export\s*\{([^}]+)\}\s*;?/);
const pairs = m[1].split(",").map((p) => p.trim()).filter(Boolean).map((p) => {
  const s = p.split(/\s+as\s+/);
  return s.length === 1 ? { local: s[0], exported: s[0] } : { local: s[0].trim(), exported: s[1].trim() };
});
const transformed = text.replace(m[0], `;return {${pairs.map((p) => `${p.exported}:${p.local}`).join(",")}};`);
const bundleId = createHash("sha256").update(text).digest("hex").slice(0, 12);

writeFileSync(OUT, `// Generated by experiment/RefreshComixBundle.ts. DO NOT EDIT BY HAND.
// To refresh: \`npm run refresh:comix\` (requires CF_CLEARANCE env var).

export const BUNDLE_INFO = {
    bundleId: ${JSON.stringify(bundleId)},
    fetchedAt: ${JSON.stringify(new Date().toISOString())},
    homepage: ${JSON.stringify(cap.title)},
    mainUrl: ${JSON.stringify(cap.mainUrl)},
    secureUrl: ${JSON.stringify(cap.secureUrl)},
    cfg: ${JSON.stringify(cap.cfg)},
    exportNames: ${JSON.stringify(pairs.map((p) => p.exported))},
} as const;

export const BUNDLE_CODE = ${JSON.stringify(transformed)};
`);
console.log(`wrote ${OUT} — bundle ${bundleId} (build ${cap.build}, exports ${pairs.map((p) => p.exported).join(",")})`);
